/* Account hub, part 1: state, helpers, Home, Libraries, a library with its campaigns, People and settings. */
const H = { acct: 'busy', role: 'asis', create: true, needsFilter: 'All', camp: { 'harbour-job': true }, linkSeq: 10, notifFilter: 'All', disc: { q: '', tag: 'All', lang: 'All' } };
const pl = (n, one, many) => `${n} ${n === 1 ? one : many}`;
const hl = (id) => HUB.libraries.find((l) => l.id === id);
const hr = (id) => HUB.repos.find((r) => r.id === id);
const libRole = (l) => (H.role === 'asis' ? l.role : H.role);
const isAdmin = (r) => r === 'Owner' || r === 'Organizer';
const parts = () => S.route.split('/');
const refresh = () => { const m = $('#main'); const y = m.scrollTop; renderMain(false); m.scrollTop = y; };
const ROLE_MEANS = { Owner: 'Full control: publishes, invites, manages people, deletes.', Organizer: 'Edits everything in it, and cannot publish, invite or change who works on it.', Author: 'Edits content only. Cannot publish, invite, manage people or delete structure.' };
const hubCallout = (icon, html, kind = '') => `<div class="callout ${kind ? 'callout--' + kind : ''}">${ic(icon)}<div class="tx">${html}</div></div>`;
const roleChip = (r) => `<span class="chip">${esc(r)}</span>`;
function repoState(r) {
  if (r.rel === 'used' && r.update && r.copied !== false) return ['Update announced', 'waiting', 'update-available'];
  if (r.rel === 'invited' && !r.copied) return ['Not copied yet', '', 'pending'];
  if (r.rel === 'gone') return ['No longer offered', 'stale', 'retired'];
  if (r.mine) return r.state === 'Draft' ? ['Draft', '', 'edit'] : ['Published ' + r.release, 'synced', 'publish'];
  return ['Copied', 'synced', 'select-item'];
}
const repoChip = (r) => { const [t, k, i] = repoState(r); return `<span class="st ${k ? 'st--' + k : ''}">${ic(i)}<span>${esc(t)}</span></span>`; };
const repoRow = (r, extra = '') => `<a class="item-row" href="#/repo/${r.id}">${ic('kind-repository')}<span class="grow"><span class="nm">${esc(r.name)}</span><span class="t-meta" style="display:block">${esc(r.mine ? 'You are its ' + r.mine : 'By ' + r.by)}${extra}</span></span>${repoChip(r)}</a>`;
const needs = () => (H.acct === 'quiet' ? [] : HUB.needs.filter((n) => H.needsFilter === 'All' || n.kind === H.needsFilter));
const myLibs = () => HUB.libraries.filter((l) => H.acct !== 'new');
const attention = (l) => l.repos.some((id) => { const r = hr(id); return r.update && r.copied !== false; });

/* ---------------------------------------------------------------- Home (D16, D27; one layout: needs and where you play beside what you run (AH1)) */
function needsBlock(filters) {
  const list = needs();
  const seg = filters ? `<div class="seg" role="radiogroup" aria-label="Show">${['All', 'Updates', 'People', 'Links'].map((f) => `<button type="button" role="radio" aria-checked="${H.needsFilter === f}" data-act="needs-filter" data-v="${f}">${f}</button>`).join('')}</div>` : '';
  const body = list.length ? list.map((n) => `<div class="need">${ic(n.icon)}<div class="tx"><b>${esc(n.title)}</b><div class="t-meta">${esc(n.meta)}</div></div><button type="button" class="btn" data-go="${n.go}">${esc(n.act)}</button></div>`).join('') : `<div class="empty-inline">${slot('caught-up', 'Catileo, curled sleep', '')}<div class="t-sub" style="margin-top:var(--s-2h)">You’re all caught up.</div><div class="muted">Nothing needs you right now.</div></div>`;
  return `<section class="listcard" aria-labelledby="h-needs"><div class="sec-h" style="padding:var(--s-3) var(--s-3) 0"><h2 id="h-needs">Needs you</h2>${seg}</div><div style="padding-bottom:var(--s-1)">${body}</div></section>`;
}
function playBlock(compact) {
  const seats = HUB.libraries.flatMap((l) => l.campaigns.filter((c) => c.me === 'Player').map((c) => ({ l, c, ch: (c.players.find((p) => p.you) || {}).ch })));
  const rows = seats.length ? seats.map(({ l, c, ch }) => `<div class="item-row"><span class="grow"><span class="nm">${esc(c.name)}</span><span class="t-meta" style="display:block">${esc(l.name)} · You play ${esc(ch)}</span></span><button type="button" class="btn btn--quiet" data-act="leave-campaign" data-l="${l.id}" data-c="${c.id}">Leave</button></div>`).join('') : '<div class="empty-inline">You do not play in a campaign yet. Open an invite link to join one.</div>';
  return `<section aria-labelledby="h-play"><div class="sec-h"><h2 id="h-play">Where you play</h2></div><div class="listcard">${rows}</div></section>`;
}
function runBlock() {
  const libs = myLibs().map((l) => { const mine = l.campaigns.filter((c) => c.me === 'GM').length; return `<a class="item-row" href="#/library/${l.id}"><span class="grow"><span class="nm">${esc(l.name)}</span><span class="t-meta" style="display:block">${pl(l.people.length || 1, 'person', 'people')} · ${pl(l.campaigns.length, 'campaign', 'campaigns')}${mine ? ' · you GM' : ''}</span></span>${attention(l) ? `<span class="st st--waiting">${ic('update-available')}<span>Updates waiting</span></span>` : ''}${roleChip(l.role)}</a>`; }).join('');
  const repos = HUB.repos.filter((r) => r.mine).map((r) => repoRow(r)).join('');
  const act = `<div class="row2" style="margin-top:var(--s-2h)">${H.create ? '<button type="button" class="btn" data-act="setup">' + ic('add') + 'Set up a library</button><button type="button" class="btn" data-act="new-repo">' + ic('add') + 'Create a repository</button>' : '<span class="t-meta">Creating a library is not open to your account yet.</span>'}</div>`;
  return `<section aria-labelledby="h-run"><div class="sec-h"><h2 id="h-run">What you run</h2></div><div class="listcard">${libs}${repos}</div>${act}</section>`;
}
function sharedBlocks() {
  const tile = (a) => `<a class="card tile" href="#/${a.route}">${ic(a.icon)}<span><b>${a.name}</b><span class="t-meta" style="display:block">${a.desc}</span></span></a>`;
  return `<h2 class="sec-title">Continue</h2><div class="grid cont stagger"><a class="card tile reveal" href="#/library/thursday/campaigns" style="display:block"><b>The harbour job</b><span class="t-meta" style="display:block">Campaign · Account · edited today</span></a><a class="card tile reveal" href="#/repo/core-equipment/use" style="display:block"><b>Core equipment</b><span class="t-meta" style="display:block">Repository · Account · opened yesterday</span></a><a class="card tile reveal" href="#/read" style="display:block"><b>Chapter 3: The blackout</b><span class="t-meta" style="display:block">Chapter · Writing · edited 2 days ago</span></a></div><h2 class="sec-title">What do you want to do?</h2><div class="grid apps stagger">${DATA.apps.map(tile).join('')}</div>`;
}
function pHubHome() {
  if (H.acct === 'new') return pFirstRun();
  const n = needs().length;
  const main = `<div class="hx-main"><div class="col-gap">${needsBlock(false)}${playBlock()}</div><div class="col-gap">${runBlock()}</div></div>`;
  return `<div class="page page--wide page-enter"><h1 class="t-title page-title">Home</h1><p class="page-sub">${esc(DATA.user.name)} · ${n ? n + ' thing' + (n > 1 ? 's need' : ' needs') + ' you' : 'nothing needs you'}</p>${main}${sharedBlocks()}</div>`;
}

/* ---------------------------------------------------------------- Libraries */
function pLibraries() {
  const cards = myLibs().map((l) => `<a class="card tile repo-card" href="#/library/${l.id}"><span class="row2" style="justify-content:space-between;width:100%"><b class="t-sub">${esc(l.name)}</b>${roleChip(l.role)}</span><span class="muted">${esc(l.desc)}</span><span class="t-meta">${pl(l.people.length || 1, 'person', 'people')} · ${pl(l.campaigns.length, 'campaign', 'campaigns')} · ${pl(l.repos.length, 'repository', 'repositories')}</span>${attention(l) ? `<span class="st st--waiting" style="align-self:flex-start">${ic('update-available')}<span>Updates waiting</span></span>` : ''}</a>`).join('');
  return `<div class="page page--wide page-enter"><div class="head-row"><div class="grow"><h1 class="t-title page-title">Libraries</h1><p class="page-sub" style="margin-bottom:0">A library holds a group’s campaigns, characters and notes.</p></div>${H.create ? `<button type="button" class="btn btn--primary" data-act="setup">${ic('add')}Set up a library</button>` : ''}</div>${H.create ? '' : '<p class="t-meta" style="margin-top:var(--s-2h)">Creating a library is not open to your account yet.</p>'}<div class="grid three stagger" style="margin-top:var(--s-4)">${cards || '<div class="empty-inline">No library is connected yet.</div>'}</div></div>`;
}

/* ---------------------------------------------------------------- A library (campaigns live here, D30) */
function libTabs(role) { return role === 'Author' ? [['overview', 'Overview'], ['people', 'People'], ['settings', 'Settings']] : [['overview', 'Overview'], ['campaigns', 'Campaigns'], ['people', 'People'], ['settings', 'Settings']]; }
function pLibrary() {
  const [, id, tab0] = parts(); const l = hl(id) || HUB.libraries[0]; const role = libRole(l);
  if (role === 'Player') return `<div class="join page-enter">${slot('no-access', 'Catileo at a closed door')}<h1 class="t-sub">This page isn’t available</h1><p class="muted">It may not exist, or you may not have access. Ask a GM or an Organizer of the library to share it with you.</p><a class="btn" href="#/hub">Go to Home</a></div>`;
  const tabs = libTabs(role); const tab = tabs.some((t) => t[0] === tab0) ? tab0 : 'overview';
  const body = { overview: libOverview, campaigns: libCampaigns, people: libPeople, settings: libSettings }[tab](l, role);
  return `<div class="page page--wide page-enter"><p class="crumb"><a href="#/libraries">Libraries</a> / ${esc(l.name)}</p><div class="head-row"><div class="grow"><h1 class="t-title">${esc(l.name)}</h1><p class="muted" style="margin-top:4px">${esc(l.desc)}</p></div><span class="chip">You are ${role === 'Owner' ? 'the Owner' : role === 'Organizer' ? 'an Organizer' : 'an Author'}</span></div><div class="subtabs" role="tablist" aria-label="${esc(l.name)}">${tabs.map(([k, n]) => `<button type="button" class="subtab" role="tab" aria-selected="${k === tab}" data-go="library/${l.id}/${k}">${n}</button>`).join('')}</div>${body}</div>`;
}
function libOverview(l, role) {
  const repos = l.repos.map((id) => repoRow(hr(id))).join('') || '<div class="empty-inline">This library draws on no repository yet.</div>';
  return `<div class="grid cont stagger" style="margin-bottom:var(--s-4)"><div class="stat-tile"><div class="t-meta">People</div><div class="v num">${l.people.length || 1}</div></div><div class="stat-tile"><div class="t-meta">Campaigns</div><div class="v num">${l.campaigns.length}</div></div><div class="stat-tile"><div class="t-meta">Repositories</div><div class="v num">${l.repos.length}</div></div></div><div class="hx-main"><section aria-labelledby="lo-r"><div class="sec-h"><h2 id="lo-r">Repositories it draws on</h2><a href="#/repositories">All repositories</a></div><div class="listcard">${repos}</div></section><section aria-labelledby="lo-a"><div class="sec-h"><h2 id="lo-a">Recent</h2></div><div class="listcard">${HUB.activity.map((a) => `<div class="item-row t-ui">${esc(a)}</div>`).join('')}</div></section></div>`;
}

/* campaigns */
function libCampaigns(l, role) {
  const list = l.campaigns.length ? l.campaigns.map((c) => campaignCard(l, c, role)).join('') : `<div class="empty-inline">${slot('empty-sessions', 'Lorenzo with a planner, Catileo asleep on it')}<div class="t-sub" style="margin-top:var(--s-2h)">No campaigns yet</div><div class="muted">A campaign is a group playing in this library.</div></div>`;
  return `<div class="head-row" style="margin-bottom:var(--s-3)"><p class="muted grow">Campaigns of ${esc(l.name)}: who plays, who runs, and the links that bring people in.</p><button type="button" class="btn btn--primary" data-act="new-campaign" data-l="${l.id}">${ic('add')}New campaign</button></div><div class="col-gap">${list}</div>`;
}
function campaignCard(l, c, role) {
  const open = H.camp[c.id]; const manage = isAdmin(role) || c.me === 'GM';
  const players = c.players.map((p) => `<div class="tr" style="grid-template-columns:minmax(0,1fr) minmax(0,1fr) 110px"><span class="nm">${esc(p.name)}${p.you ? ' <span class="t-meta">You</span>' : ''}</span><span><span class="lbl">Plays</span>${esc(p.ch)}</span><span>${manage && !p.you ? `<button type="button" class="btn btn--quiet" data-act="remove-player" data-l="${l.id}" data-c="${c.id}" data-p="${esc(p.name)}">Remove</button>` : p.you && c.me === 'Player' ? `<button type="button" class="btn btn--quiet" data-act="leave-campaign" data-l="${l.id}" data-c="${c.id}">Leave</button>` : ''}</span></div>`).join('') || '<div class="tr"><span class="muted">No players yet. Make a player link to bring some in.</span></div>';
  const links = c.links.length ? c.links.map((k) => `<div class="tr" style="grid-template-columns:minmax(0,1fr) minmax(0,1fr) minmax(0,1fr) 190px"><span class="nm">${k.kind}</span><span><span class="lbl">Made</span>${k.made} · ends ${k.ends}</span><span class="num"><span class="lbl">Used</span>${k.uses}</span><span class="row2">${linkChip(k.status)}${k.status === 'active' ? `<button type="button" class="btn btn--quiet" data-act="revoke-link" data-l="${l.id}" data-c="${c.id}" data-k="${k.id}">Revoke</button>` : ''}</span></div>`).join('') : '<div class="tr"><span class="muted">No links.</span></div>';
  return `<section class="listcard" aria-labelledby="c-${c.id}"><div class="item-row click" data-act="toggle-camp" data-c="${c.id}" role="button" tabindex="0" aria-expanded="${!!open}"><span class="grow"><span class="nm t-sub" id="c-${c.id}">${esc(c.name)}</span><span class="t-meta" style="display:block">${c.players.length} players · GM ${c.gms.map(esc).join(', ')}</span></span>${roleChip(c.me === 'GM' ? 'You GM' : 'You play')}${ic(open ? 'collapse' : 'expand')}</div>${open ? `<div style="padding:var(--s-3)" class="col-gap"><div><div class="sec-h"><h2 class="t-ui" style="font-weight:600">Players</h2></div><div class="tbl2"><div class="th" style="grid-template-columns:minmax(0,1fr) minmax(0,1fr) 110px"><span>Name</span><span>Plays</span><span></span></div>${players}</div></div>${manage ? `<div><div class="sec-h"><h2 class="t-ui" style="font-weight:600">Links</h2><span class="row2"><button type="button" class="btn" data-act="make-link" data-l="${l.id}" data-c="${c.id}" data-kind="player">${ic('add')}Make a player link</button><button type="button" class="btn" data-act="make-link" data-l="${l.id}" data-c="${c.id}" data-kind="gm">Invite a GM</button></span></div><div class="tbl2"><div class="th" style="grid-template-columns:minmax(0,1fr) minmax(0,1fr) minmax(0,1fr) 190px"><span>Link</span><span>Made, ends</span><span>Used</span><span></span></div>${links}</div></div>` : '<p class="t-meta">Only the campaign’s GMs and the library’s administrators make links.</p>'}</div>` : ''}</section>`;
}
const linkChip = (s) => ({ active: '<span class="st st--synced">' + ic('select-item') + '<span>Active</span></span>', used: '<span class="st st--stale">' + ic('stale') + '<span>Used up</span></span>', expired: '<span class="st st--stale">' + ic('stale') + '<span>Expired</span></span>', revoked: '<span class="st st--conflict">' + ic('revoke') + '<span>Revoked</span></span>' }[s]);

/* ---------------------------------------------------------------- People (ADR 0212: what a role sees) */
function peopleBlock(ent, role, kind) {
  const meaning = `<section class="card" aria-labelledby="pm"><h2 id="pm" class="t-ui" style="font-weight:600;margin-bottom:var(--s-2)">What each role allows</h2>${Object.entries(ROLE_MEANS).map(([r, m]) => `<div style="padding:4px 0"><b>${r}</b> <span class="muted">${m}</span></div>`).join('')}</section>`;
  if (role === 'Author') return `<div class="col-gap" style="max-width:720px"><div class="card"><b>You: Author</b><p class="muted" style="margin-top:4px">${ROLE_MEANS.Author}</p></div>${meaning}<div><button type="button" class="btn btn--danger" data-act="leave" data-n="${esc(ent.name)}" data-kind="${kind}">Leave this ${kind}</button></div></div>`;
  const owner = role === 'Owner';
  const people = ent.people || [];
  const rows = people.map((p, i) => `<div class="tr" style="grid-template-columns:minmax(0,1.4fr) minmax(0,1fr) minmax(0,1fr) 110px"><span class="nm">${esc(p.name)}${p.you ? ' <span class="t-meta">You</span>' : ''}</span><span>${owner && !p.you ? `<span class="selectwrap"><select class="select" aria-label="Role of ${esc(p.name)}" data-act="role" data-i="${i}">${['Owner', 'Organizer', 'Author'].map((r) => `<option ${r === p.role ? 'selected' : ''}>${r}</option>`).join('')}</select>${ic('expand')}</span>` : esc(p.role)}</span><span class="muted"><span class="lbl">Added by</span>${esc(p.by || '')}</span><span>${owner && !p.you ? `<button type="button" class="btn btn--quiet" data-act="remove-person" data-i="${i}">Remove</button>` : ''}</span></div>`).join('');
  const add = owner ? `<div class="card col-gap"><h2 class="t-ui" style="font-weight:600">Add someone</h2><div class="row2"><label class="visually-hidden" for="addp">Email or nickname</label><input id="addp" class="input" style="flex:1;min-width:200px" placeholder="Email or nickname"><span class="selectwrap" style="width:150px"><select class="select" id="addr" aria-label="Role"><option>Author</option><option>Organizer</option><option>Owner</option></select>${ic('expand')}</span><button type="button" class="btn btn--primary" data-act="add-person">Add</button></div><p class="t-meta">A person is added as an Author unless you choose another role, the least a role can be.</p><div class="row2"><button type="button" class="btn" data-act="make-role-link" data-kind="${kind}">Make a role link</button><span class="t-meta">A link is shown once and ends. Up to 10 people can use it.</span></div></div>` : hubCallout('info', `<b>Only an Owner can change who works here.</b> You can read the list.`);
  return `<div class="col-gap">${meaning}<div class="tbl2"><div class="th" style="grid-template-columns:minmax(0,1.4fr) minmax(0,1fr) minmax(0,1fr) 110px"><span>Name</span><span>Role</span><span>Added by</span><span></span></div>${rows || '<div class="tr"><span class="muted">Just you.</span></div>'}</div>${add}</div>`;
}
function libPeople(l, role) { return peopleBlock(l, role, 'library'); }

/* ---------------------------------------------------------------- Settings of a library */
function libSettings(l, role) {
  const ed = isAdmin(role); const dis = ed ? '' : 'disabled';
  const del = role === 'Owner' && H.create ? `<button type="button" class="btn btn--danger" data-act="delete-lib" data-n="${esc(l.name)}" data-l="${l.id}">Delete ${esc(l.name)}…</button>` : `<p class="t-meta">${role === 'Owner' ? 'Deleting also needs a permission your account does not have.' : 'Only an Owner can delete this library.'}</p>`;
  return `<div class="form" data-form><section class="form-sec"><div><h2 class="t-heading">General</h2><p class="muted" style="margin-top:4px">The name and description people see.</p>${ed ? '' : '<p class="t-meta" style="margin-top:8px">Only an Owner or an Organizer can edit this.</p>'}</div><div class="fields"><div><label class="label" for="s-n">Library name</label><input id="s-n" class="input" data-f value="${esc(l.name)}" ${dis}></div><div><label class="label" for="s-s">Link name</label><input id="s-s" class="input t-code" data-f value="${l.id}" ${dis}><div class="help">Changing it stops links that use the old one from working.</div></div><div><label class="label" for="s-d">Description</label><input id="s-d" class="input" data-f value="${esc(l.desc)}" ${dis}></div></div></section><section class="form-sec"><div><h2 class="t-heading">Leave this library</h2><p class="muted" style="margin-top:4px">You lose access. A GM can step down without leaving.</p></div><div><button type="button" class="btn" data-act="leave" data-n="${esc(l.name)}" data-kind="library">Leave ${esc(l.name)}…</button></div></section><section class="form-sec"><div><h2 class="t-heading">Delete this library</h2><p class="muted" style="margin-top:4px">This removes its notes for everyone. It cannot be undone.</p></div><div>${del}</div></section></div>`;
}

/* ---------------------------------------------------------------- shared behaviour of the hub's pages */
let HFORM0 = null;
function bindForm() {
  const m = $('#main'); const fs = $$('[data-f]', m); if (!fs.length) { $('#savebar').toggleAttribute('data-open', false); m.onchange = hubChange; return; }
  HFORM0 = fs.map((f) => f.type === 'checkbox' ? f.checked : f.value);
  const upd = () => { const n = fs.filter((f, i) => (f.type === 'checkbox' ? f.checked : f.value) !== HFORM0[i]).length; const b = $('#savebar'); if (n) b.innerHTML = `<div><div class="savebar-in" role="region" aria-label="Unsaved changes"><span style="display:inline-flex;align-items:center;gap:6px"><span style="color:var(--warning);display:inline-flex">${ic('pending')}</span>${n} ${n === 1 ? 'change' : 'changes'} not saved</span><span class="grow"></span><button type="button" class="btn" data-sb="discard">Discard</button><button type="button" class="btn btn--primary" data-sb="save">Save changes</button></div></div>`; b.toggleAttribute('data-open', n > 0); };
  m.oninput = upd; m.onchange = (e) => { upd(); hubChange(e); };
  $('#savebar').onclick = (e) => { const a = e.target.closest('[data-sb]'); if (!a) return; if (a.dataset.sb === 'discard') { fs.forEach((f, i) => { if (f.type === 'checkbox') f.checked = HFORM0[i]; else f.value = HFORM0[i]; }); upd(); toast({ title: 'Changes discarded' }); } else { HFORM0 = fs.map((f) => f.type === 'checkbox' ? f.checked : f.value); upd(); if (S.offline) { S.waiting++; renderStrip(); updateStatus(); } toast({ title: S.offline ? 'Saved on this device' : 'Saved', text: S.offline ? 'It is sent when you are back online.' : undefined }); } };
}
function confirmByName(name, title, body, ok) {
  openDialog({ title, label: 'alertdialog', body: `<p class="muted t-body" style="margin-bottom:var(--s-2h)">${body}</p><label class="label" for="cn-i">Type <b style="color:var(--text-primary)">${esc(name)}</b> to confirm</label><input id="cn-i" class="input" data-autofocus autocomplete="off"><div class="help" id="cn-h">Type the full name to continue.</div>`, actions: [{ label: 'Cancel' }, { label: title.replace('?', '').replace(/^Delete/, 'Delete'), kind: 'danger', disabled: true, fn: ok }], init: (d) => { const b = $('[data-a="1"]', d), i = $('#cn-i', d); i.addEventListener('input', () => { const good = i.value.trim() === name; setDisabled(b, !good); $('#cn-h', d).textContent = good ? 'This cannot be undone.' : 'Type the full name to continue.'; }); } });
}
function confirmSimple(title, body, label, ok, danger = true) { openDialog({ title, label: 'alertdialog', body: `<p class="muted t-body">${body}</p>`, actions: [{ label: 'Cancel', auto: true }, { label, kind: danger ? 'danger' : 'primary', fn: ok }] }); }
function showOnce(title, intro, link, note) {
  openDialog({ title, body: `<p class="muted t-body" style="margin-bottom:var(--s-2h)">${intro}</p><div class="linkbox"><input class="input" readonly value="${esc(link)}" aria-label="The link" data-autofocus><button type="button" class="btn" id="so-copy">${ic('copy')}Copy</button></div><p class="t-meta" style="margin-top:var(--s-2h)">${note}</p>`, actions: [{ label: 'Done', kind: 'primary' }], init: (d) => { $('#so-copy', d).onclick = () => { try { navigator.clipboard.writeText(link); } catch (e) { /* ignore */ } toast({ title: 'Link copied' }); }; } });
}
